import { describe, it, expect } from "vitest";
import { renderHook, act } from "@testing-library/react";
import { useUndoableState } from "./use-undoable-state.js";

describe("useUndoableState", () => {
  function setup(initial) {
    const harness = renderHook(() => useUndoableState(initial));
    return {
      getState: () => harness.result.current[0],
      setState: (v) =>
        act(() => {
          harness.result.current[1](v);
        }),
      controls: () => harness.result.current[2],
    };
  }

  it("a sequence of sets then undos lands on exact values", () => {
    const h = setup(0);
    h.setState(1);
    h.setState(2);
    h.setState(3);
    expect(h.getState()).toBe(3);

    act(() => h.controls().undo());
    expect(h.getState()).toBe(2);

    act(() => h.controls().undo());
    expect(h.getState()).toBe(1);

    act(() => h.controls().undo());
    expect(h.getState()).toBe(0);

    // Redo walks forward through the exact values again.
    act(() => h.controls().redo());
    expect(h.getState()).toBe(1);
    act(() => h.controls().redo());
    expect(h.getState()).toBe(2);
    act(() => h.controls().redo());
    expect(h.getState()).toBe(3);
  });

  it("redo stack clears on a new set", () => {
    const h = setup("a");
    h.setState("b");
    h.setState("c");

    act(() => h.controls().undo());
    expect(h.getState()).toBe("b");
    expect(h.controls().canRedo).toBe(true);

    h.setState("x");
    expect(h.getState()).toBe("x");
    expect(h.controls().canRedo).toBe(false);

    act(() => h.controls().redo());
    expect(h.getState()).toBe("x"); // redo is inert after the new set

    act(() => h.controls().undo());
    expect(h.getState()).toBe("a");
  });

  it("setState with an Object.is-equal value does not push history", () => {
    const h = setup({ count: 0 });
    const sameRef = h.getState();

    h.setState(sameRef); // identical reference
    expect(h.controls().canUndo).toBe(false);
    expect(h.controls().canUndo).toBe(false);

    h.setState({ count: 0 }); // deep-equal but not Object.is → pushes
    expect(h.controls().canUndo).toBe(true);

    // NaN === NaN is false but Object.is(NaN, NaN) is true → still a no-op.
    h.setState(NaN);
    act(() => h.controls().undo());
    expect(h.getState()).toEqual({ count: 0 });
    expect(h.controls().canUndo).toBe(false);

    // Functional updates are also checked against Object.is.
    const current = h.getState();
    h.setState((prev) => prev);
    expect(h.controls().canUndo).toBe(false);
    expect(h.getState()).toBe(current);
  });

  it("canUndo/canRedo flags are correct at both boundaries", () => {
    const h = setup(0);

    // At the oldest boundary: nothing to undo or redo.
    expect(h.controls().canUndo).toBe(false);
    expect(h.controls().canRedo).toBe(false);

    h.setState(1);
    expect(h.controls().canUndo).toBe(true);
    expect(h.controls().canRedo).toBe(false);

    act(() => h.controls().undo());
    // Back at the initial state: canUndo false again, redo available.
    expect(h.getState()).toBe(0);
    expect(h.controls().canUndo).toBe(false);
    expect(h.controls().canRedo).toBe(true);

    act(() => h.controls().redo());
    // At the newest boundary again.
    expect(h.getState()).toBe(1);
    expect(h.controls().canUndo).toBe(true);
    expect(h.controls().canRedo).toBe(false);
  });

  it("caps history at 50 entries, evicting the oldest", () => {
    const h = setup(-1);
    // Push states 0..60 → 61 sets total; only the last 50 presents remain.
    for (let i = 0; i <= 60; i++) {
      h.setState(i);
    }
    expect(h.getState()).toBe(60);

    // Undo all 50 available entries: should land exactly on state 10.
    for (let i = 0; i < 50; i++) {
      act(() => h.controls().undo());
    }
    expect(h.getState()).toBe(10);
    // History exhausted — state 10 is the oldest surviving entry.
    expect(h.controls().canUndo).toBe(false);
    expect(h.controls().canRedo).toBe(true);

    act(() => h.controls().redo());
    expect(h.getState()).toBe(11);
  });
});

