import { useCallback, useRef, useState } from "react";

const MAX_HISTORY = 50;

/**
 * State hook with undo/redo history.
 *
 * Returns [state, setState, { undo, redo, canUndo, canRedo, clear }].
 * - Keeps at most MAX_HISTORY (50) history entries (evicts oldest).
 * - A set whose value is Object.is-equal to the current state is a no-op
 *   (no history entry pushed). Works for direct values and updater fns.
 * - Setting a new value clears the redo stack.
 */
export function useUndoableState(initial) {
  const [state, setStateRaw] = useState(initial);
  // past: oldest ... newest (newest last); future: redo stack (next-redo first).
  const [past, setPast] = useState([]);
  const [future, setFuture] = useState([]);
  // Ref mirror of the current state for Object.is checks inside callbacks.
  const stateRef = useRef(state);
  stateRef.current = state;

  const setState = useCallback((value) => {
    setStateRaw((prev) => {
      const next = typeof value === "function" ? value(prev) : value;
      if (Object.is(next, prev)) return prev; // no-op: no history entry
      setPast((p) => {
        const updated = [...p, prev];
        return updated.length > MAX_HISTORY
          ? updated.slice(updated.length - MAX_HISTORY)
          : updated;
      });
      setFuture([]); // new branch: discard redo stack
      return next;
    });
  }, []);

  const undo = useCallback(() => {
    setStateRaw((current) => {
      if (past.length === 0) return current;
      const previous = past[past.length - 1];
      setPast((p) => p.slice(0, -1));
      setFuture((f) => [current, ...f]);
      return previous;
    });
  }, [past]);

  const redo = useCallback(() => {
    setStateRaw((current) => {
      if (future.length === 0) return current;
      const next = future[0];
      setFuture((f) => f.slice(1));
      setPast((p) => [...p, current]);
      return next;
    });
  }, [future]);

  const clear = useCallback(() => {
    setPast([]);
    setFuture([]);
  }, []);

  return [
    state,
    setState,
    {
      undo,
      redo,
      canUndo: past.length > 0,
      canRedo: future.length > 0,
      clear,
    },
  ];
}

